select con.con_id as conId, ject.p_name as preName, con.Con_Payment_State as conPaymentState, con.con_name as conName, pany.c_name AS companyPartybName, con.con_type as conCategory, con.Con_Code as conCode, con.Con_Money_Total as conAmtStr, ( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ) AS conSupplementAmtStr, app.sa_approved_amt as settlementAmtStr, con.con_Party_A_Agent as conPartyAAgent, con.con_Party_B_Agent as conPartyBAgent, con.con_Party_B_Agent_Tel as conPartyBAgentTel, (select sum(COALESCE(Pay_Apply,0)) from con_pay conp where conp.con_id =con.con_id and Pay_State NOT IN (0, 3, 7)) as conApplyAmtApprovalStr, (select sum(COALESCE(Pay_Apply,0)) from con_pay conp where conp.con_id =con.con_id and Pay_State in 7) as conApplyAmtApprovalComStr, (select sum(COALESCE(tiondtl.Fad_Actual_Payment,0)) from Fund_Allocation tion left join Fund_Allocation_Dtl tiondtl on tion.id = tiondtl.Fa_Id where tion.state NOT IN (0, 3, 7) and tiondtl.con_id = con.con_id ) as conDisAmtApprovalStr, (select sum(COALESCE(tiondtl.Fad_Actual_Payment,0)) from Fund_Allocation tion left join Fund_Allocation_Dtl tiondtl on tion.id = tiondtl.Fa_Id where tion.state = 7 and tiondtl.con_id = con.con_id ) as conDisApprovalCompletedStr from con_contract con left join pre_project ject on con.con_project_id = ject.p_id left join SYS_Company pany on con.Con_Party_B_Id = pany.c_id left join Inv_Settlement_Apply app on con.con_id = app.con_id
con.Con_Payment_State = #{contractManageVo.conPaymentState}
and ject.p_name like concat('%',#{contractManageVo.preName},'%')
and likePname(#{contractManageVo.preName},ject.P_Id)=true
and likeCname(#{contractManageVo.companyPartybName},pany.C_Id)=true
and ject.p_name like concat('%',#{contractManageVo.preName},'%')
and pany.c_name like concat('%',#{contractManageVo.companyPartybName},'%')
and con.con_name like concat('%',#{contractManageVo.conName},'%')
and pany.c_name like concat('%',#{contractManageVo.companyPartybName},'%')
and con.con_type like concat('%',#{contractManageVo.conCategory},'%')
and con.Con_Code like concat('%',#{contractManageVo.conCode},'%')
AND con.Con_Money_Total >= #{contractManageVo.conAmtStr}
AND con.Con_Money_Total <= #{contractManageVo.conAmtEnd}
AND con.Con_Money_Total BETWEEN #{contractManageVo.conAmtStr} AND #{contractManageVo.conAmtEnd}
AND ( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ) >= #{contractManageVo.conSupplementAmtStr}
AND ( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ) <= #{contractManageVo.conAmtEnd}
AND ( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ) BETWEEN #{contractManageVo.conSupplementAmtStr} AND #{contractManageVo.conSupplementAmtEnd}
AND app.sa_approved_amt >= #{contractManageVo.settlementAmtStr}
AND app.sa_approved_amt <= #{contractManageVo.settlementAmtEnd}
AND app.sa_approved_amt BETWEEN #{contractManageVo.settlementAmtStr} AND #{contractManageVo.settlementAmtEnd}
and con.con_Party_A_Agent like concat('%',#{contractManageVo.conPartyAAgent},'%')
and con.con_Party_B_Agent like concat('%',#{contractManageVo.conPartyBAgent},'%')
and con.con_Party_B_Agent_Tel like concat('%',#{contractManageVo.conPartyBAgentTel},'%')

