AND app.sa_approved_amt BETWEEN #{contractManageVo.settlementAmtStr} AND #{contractManageVo.settlementAmtEnd}

select pre.p_id , pre.p_name as preName, con.con_id as conId, con.con_name as conName, panya.c_name as companyPartyAName, panyb.c_name as companyPartybName, con.Con_Money_Total as conAmtStr, ( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ) AS conSupplementAmtStr, app.sa_approved_amt as settlementAmtStr, con.con_Party_A_Agent as conPartyAAgent from con_contract con left join pre_project pre on con.con_project_id = pre.p_id left join sys_company panya ON con.Con_Party_A_Id = panya.c_id left join sys_company panyb ON con.Con_Party_B_Id = panyb.c_id left join Inv_Settlement_Apply app on con.con_id = app.con_id
