SELECT EXTRACT(MONTH FROM cpaf_apply_time) AS "month", SUM(cpaf_application) AS amt, con_id as conId FROM Con_Pay_Apply_Flow
state = 7
and EXTRACT(YEAR FROM cpaf_apply_time) = #{year}
and con_id in
#{ids}
GROUP BY EXTRACT(MONTH FROM cpaf_apply_time),con_id order by EXTRACT(MONTH FROM cpaf_apply_time)

SELECT EXTRACT(MONTH FROM tion.Fa_Disbursement_Time) AS "month", SUM(tiondtl.Fad_Actual_Payment) AS amt, tiondtl.con_id as conId FROM Fund_Allocation tion left join Fund_Allocation_Dtl tiondtl on tion.id = tiondtl.Fa_Id
tion.state = 7
and EXTRACT(YEAR FROM tion.Fa_Disbursement_Time) = #{year}
and tiondtl.con_id in
#{ids}
GROUP BY EXTRACT(MONTH FROM tion.Fa_Disbursement_Time),tiondtl.con_id order by EXTRACT(MONTH FROM tion.Fa_Disbursement_Time)

select decl.id as id, pre.p_name as pName, con.con_id as conId, con.con_name as conName, con.con_code as conCode, panya.c_name as contrPartyAName , panyb.c_name as contrPartyBName, con.Con_Money_Total as conAmtStr, app.sa_approved_amt as settlementAmtStr, decl.Pd_Date as progressDateStr, dtl.Pdd_Progress as progressStr, decl.Create_Time as declareDateStr, decl.Create_Uname as declarePeople, decl.State as state, decl.Pd_Remark as pdRemark from Progress_Declaration decl left join Progress_Declaration_Dtl dtl on dtl.pd_id = decl.id left join pre_project pre on pre.p_id = dtl.p_id left join con_contract con on con.con_id = dtl.con_id left join sys_company panya ON con.Con_Party_A_Id = panya.c_id left join sys_company panyb ON con.Con_Party_B_Id = panyb.c_id left join Inv_Settlement_Apply app on con.con_id = app.con_id
1=1
and likePname(#{progressDeclarationVo.pName},pre.P_Id)=true
and (likeCname(#{progressDeclarationVo.contrPartyAName},panya.C_Id)=true or vpanya.c_id =#{companyPartyAName})
and likeCname(#{progressDeclarationVo.contrPartyBName},panyb.C_Id)=true
and pre.p_name like concat('%',#{progressDeclarationVo.pName},'%')
and panya.c_name like concat('%',#{progressDeclarationVo.contrPartyAName},'%')
and panyb.c_name like concat('%',#{progressDeclarationVo.contrPartyBName},'%')
and con.con_id = #{progressDeclarationVo.conId}
