and con.con_code like concat('%',#{progressDeclarationVo.conCode},'%')
AND dtl.Pdd_Progress >= #{progressDeclarationVo.progressStr}
AND dtl.Pdd_Progress <= #{progressDeclarationVo.progressEnd}
AND dtl.Pdd_Progress BETWEEN #{progressDeclarationVo.progressStr} AND #{progressDeclarationVo.progressEnd}
and decl.Create_Uname like concat('%',#{progressDeclarationVo.declarePeople},'%')
and decl.Pd_Remark like concat('%',#{progressDeclarationVo.pdRemark},'%')
and decl.State = #{progressDeclarationVo.state}
AND con.Con_Money_Total >= #{progressDeclarationVo.conAmtStr}
AND con.Con_Money_Total <= #{progressDeclarationVo.conAmtEnd}
AND con.Con_Money_Total BETWEEN #{progressDeclarationVo.conAmtStr} AND #{progressDeclarationVo.conAmtEnd}
AND app.sa_approved_amt >= #{progressDeclarationVo.settlementAmtStr}
AND app.sa_approved_amt <= #{progressDeclarationVo.settlementAmtEnd}
AND app.sa_approved_amt BETWEEN #{progressDeclarationVo.settlementAmtStr} AND #{progressDeclarationVo.settlementAmtEnd}
AND decl.Pd_Date >= #{progressDeclarationVo.progressDateStr}
AND decl.Pd_Date <= #{progressDeclarationVo.progressDateEnd}
