AND decl.Create_Time >= #{progressDeclarationVo.declareDateStr}
AND decl.Create_Time <= #{progressDeclarationVo.declareDateEnd}
AND decl.Create_Time BETWEEN #{progressDeclarationVo.declareDateStr} AND #{progressDeclarationVo.declareDateEnd}

select pre.p_id as pId, pre.p_name as preName, con.con_id as conId, con.con_name as conName, panya.c_name as companyPartyAName, panyb.c_name as companyPartybName, con.con_type as conCategory, con.Con_Code as conCode, con.Con_Money_Total as conAmtStr, ( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ) AS conSupplementAmtStr, pre.P_Final as pFinal, app.sa_approved_amt as settlementAmtStr, con.Con_Date as signDateStr, pre.P_Actual_Complete_Date as completedDateStr, dep.d_name as dName, con.con_Party_A_Agent as conPartyAAgent, con.con_Party_B_Agent as conPartyBAgent, con.con_Party_B_Agent_Tel as conPartyBAgentTel, con.Con_Approval_State as state, con.Con_Payment_State as conPaymentState, con.Con_Create_User_Name as contrCreatePeople, con.Con_Create_Time as contrCreateDateStr, (select sum(COALESCE(Pay_Apply,0)) from con_pay conp where conp.con_id =con.con_id and Pay_State NOT IN (0, 3, 7)) as conApplyAmtApprovalStr, (select sum(COALESCE(Pay_Apply,0)) from con_pay conp where conp.con_id =con.con_id and Pay_State = 7) as conApplyAmtApprovalComStr, (select sum(COALESCE(tiondtl.Fad_Actual_Payment,0)) from Fund_Allocation tion left join Fund_Allocation_Dtl tiondtl on tion.id = tiondtl.Fa_Id where tion.state NOT IN (0, 3, 7) and tiondtl.con_id = con.con_id ) as conDisAmtApprovalStr, (select sum(COALESCE(tiondtl.Fad_Actual_Payment,0)) from Fund_Allocation tion left join Fund_Allocation_Dtl tiondtl on tion.id = tiondtl.Fa_Id where tion.state = 7 and tiondtl.con_id = con.con_id ) as conDisApprovalCompletedStr, (select sum(COALESCE(cpaf_application,0)) From Con_Pay_Apply_Flow flow where flow.con_id = con.con_id and flow.state NOT IN (0, 3, 7)) as fundsPaymentStr, (select sum(COALESCE(cpaf_application,0)) From Con_Pay_Apply_Flow flow where flow.con_id = con.con_id and flow.state = 7) as fundsPaymentEnd
From con_contract con left join pre_project pre on con.con_project_id = pre.p_id left join sys_company panya ON con.Con_Party_A_Id = panya.c_id left join sys_company panyb ON con.Con_Party_B_Id = panyb.c_id left join Inv_Settlement_Apply app on con.con_id = app.con_id left join SYS_Department dep on pre.P_Competent_Department = dep.d_id
1=1
and likePname(#{vo.preName},pre.P_Id)=true
and likeCname(#{vo.companyPartyAName},panya.C_Id)=true
and likeCname(#{vo.companyPartybName},panyb.C_Id)=true
and pre.p_name like concat('%',#{vo.preName},'%')
and panya.c_name like concat('%',#{vo.companyPartyAName},'%')
and panyb.c_name like concat('%',#{vo.companyPartybName},'%')
and con.con_name like concat('%',#{vo.conName},'%')
and con.con_code like concat('%',#{vo.conCode},'%')
and con.con_type like concat('%',#{vo.conCategory},'%')
and con.con_Party_A_Agent like concat('%',#{vo.conPartyAAgent},'%')
and con.con_Party_B_Agent like concat('%',#{vo.conPartyBAgent},'%')
and con.con_Party_B_Agent_Tel like concat('%',#{vo.conPartyBAgentTel},'%')
and dep.d_name like concat('%',#{vo.dName},'%')
