AND ( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ) <= #{vo.conSupplementAmtEnd}
AND ( con.Con_Money_Total + COALESCE( (SELECT SUM( CASE WHEN cc.Con_Sup_Change_Mon_Type = 1 THEN cc.Con_Sup_Change_Money WHEN cc.Con_Sup_Change_Mon_Type = 0 THEN -Con_Sup_Change_Money ELSE 0 END ) FROM Con_Contract cc WHERE cc.Con_Sup = '是' AND cc.Con_Master_Con_Id IS NOT NULL AND cc.Con_Approval_State = 7 AND cc.Con_Master_Con_Id = con.con_id), 0 ) ) BETWEEN #{vo.conSupplementAmtStr} AND #{vo.conSupplementAmtEnd}
