select pany.c_name as cName, pre.p_name as pName, pre.p_id as pId, con.con_id as conId, con.con_name as conName, con.con_type as conType, con.Con_Money_Total, app.fa_Approved_Amt as pFinal , pay.Pay_Apply, pany.c_id as cId, pay.Pay_Total, dep.d_name, dep.d_id as dId, con.con_Party_A_Agent, pay.Pay_Create_Time, pay.Pay_State_Time, pay.pay_id as payId, flow.cpaf_Application as actualPaymentAmt, sett.as_Audited_Amount as asAuditedAmount, paudit.pa_Examine_Approve as paExamineApprove From con_pay pay left join pre_project pre on pre.p_id = pay.p_id left join con_contract con on pay.con_id = con.con_id left join sys_company pany on pany.c_id = con.Con_Payee_Id left join SYS_Department dep on con.con_Department = dep.d_id left join Audit_Settlement sett on sett.con_id = con.con_id left join Inv_Final_Accounts_Apply app on app.con_id = con.con_id left join Con_Pay_Apply_Flow flow on flow.con_id = con.con_id left join Preliminary_Audit paudit on paudit.con_id = con.con_id
pay.Pay_State = 7
and pany.c_id = #{panyId}
